import{_ as a,c as e,a2 as o,o as r}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"成本与部署运营概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/10-cost-deployment/01-cost/01-overview.md","filePath":"ai/10-cost-deployment/01-cost/01-overview.md","lastUpdated":1783608971000}'),d={name:"ai/10-cost-deployment/01-cost/01-overview.md"};function l(i,t,n,s,h,c){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="成本与部署运营概述" tabindex="-1">成本与部署运营概述 <a class="header-anchor" href="#成本与部署运营概述" aria-label="Permalink to &quot;成本与部署运营概述&quot;">​</a></h1><p>成本与部署运营关注 AI 应用的运行成本、性能优化、本地部署和资源规划。企业级 AI 应用不仅要能跑通，还要控制 Token 成本、模型成本、GPU 资源和高并发下的稳定性。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>控制成本</strong>：通过模型选型、路由、缓存、批处理和 Prompt 压缩降低消耗。</li><li><strong>提升性能</strong>：优化延迟、吞吐、上下文长度和高频请求处理能力。</li><li><strong>支撑部署</strong>：规划本地模型、vLLM、GPU 资源、高可用和容量评估。</li></ul><h2 id="运营能力" tabindex="-1">运营能力 <a class="header-anchor" href="#运营能力" aria-label="Permalink to &quot;运营能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>成本模型</td><td>理解 Token、模型单价、请求量、上下文长度和预算配额</td></tr><tr><td>性能优化</td><td>使用模型路由、缓存、批处理、Prompt 压缩和小模型替代</td></tr><tr><td>私有部署</td><td>使用 Ollama、vLLM 和 GPU 资源部署本地模型服务</td></tr><tr><td>运维治理</td><td>建立容量评估、高可用、灾备和成本看板</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先建立 Token 成本模型，明确哪些因素决定 AI 应用成本。</li><li>再学习缓存、批处理、模型路由和 Prompt 压缩等优化手段。</li><li>最后掌握本地与私有化部署方案，支撑企业生产环境运行。</li></ol>',8)]))}const u=a(d,[["render",l]]);export{p as __pageData,u as default};
